const fs=require('fs'),path=require('path'),{execSync}=require('child_process');
const files={"backend/src/controllers/admin.controller.ts":"// src/controllers/admin.controller.ts\nimport { Request, Response } from \"express\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { paginate, sanitizeUser } from \"../utils/helpers\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport bcrypt from \"bcryptjs\";\n\n// ── Dashboard Stats ───────────────────────────────────────────────────────────\nexport const getDashboardStats = async (_req: AuthRequest, res: Response) => {\n  const [\n    totalUsers, activeUsers, suspendedUsers,\n    totalStores, activeStores,\n    totalOrders, totalRevenue, platformFees,\n    failedPayments, openTickets,\n    newUsersThisMonth, revenueThisMonth,\n  ] = await Promise.all([\n    await prisma.user.count({ where: { role: \"STORE_OWNER\" } }),\n    await prisma.user.count({ where: { role: \"STORE_OWNER\", status: \"ACTIVE\" } }),\n    await prisma.user.count({ where: { role: \"STORE_OWNER\", status: \"SUSPENDED\" } }),\n    await prisma.store.count(),\n    await prisma.store.count({ where: { status: \"ACTIVE\" } }),\n    await prisma.order.count(),\n    await prisma.payment.aggregate({ where: { status: \"SUCCESS\" }, _sum: { amount: true } }),\n    await prisma.payment.aggregate({ where: { status: \"SUCCESS\" }, _sum: { platformFee: true } }),\n    await prisma.payment.count({ where: { status: \"FAILED\" } }),\n    await prisma.supportTicket.count({ where: { status: { in: [\"OPEN\",\"IN_PROGRESS\"] } } }),\n    await prisma.user.count({\n      where: {\n        role: \"STORE_OWNER\",\n        createdAt: { gte: new Date(new Date().getFullYear(), new Date().getMonth(), 1) },\n      },\n    }),\n    await prisma.payment.aggregate({\n      where: {\n        status: \"SUCCESS\",\n        createdAt: { gte: new Date(new Date().getFullYear(), new Date().getMonth(), 1) },\n      },\n      _sum: { amount: true },\n    }),\n  ]);\n\n  // Monthly revenue for last 7 months\n  const months = Array.from({ length: 7 }, (_, i) => {\n    const d = new Date();\n    d.setMonth(d.getMonth() - (6 - i));\n    return new Date(d.getFullYear(), d.getMonth(), 1);\n  });\n\n  const monthlyRevenue = await Promise.all(\n    months.map(async (start) => {\n      const end = new Date(start.getFullYear(), start.getMonth() + 1, 0);\n      const agg = await prisma.payment.aggregate({\n        where: { status: \"SUCCESS\", createdAt: { gte: start, lte: end } },\n        _sum:  { amount: true, platformFee: true },\n      });\n      return {\n        month:    start.toLocaleString(\"default\", { month: \"short\" }),\n        revenue:  agg._sum.amount || 0,\n        fees:     agg._sum.platformFee || 0,\n      };\n    })\n  );\n\n  // Gateway distribution\n  const gatewayStats = await prisma.payment.groupBy({\n    by:    [\"gateway\"],\n    where: { status: \"SUCCESS\" },\n    _sum:  { amount: true },\n    _count:{ id: true },\n  });\n\n  return res.json({\n    success: true,\n    data: {\n      users:         { total: totalUsers, active: activeUsers, suspended: suspendedUsers, newThisMonth: newUsersThisMonth },\n      stores:        { total: totalStores, active: activeStores },\n      orders:        { total: totalOrders },\n      revenue:       { total: totalRevenue._sum.amount || 0, thisMonth: revenueThisMonth._sum.amount || 0 },\n      platformFees:  { total: platformFees._sum.platformFee || 0 },\n      failedPayments,\n      openTickets,\n      monthlyRevenue,\n      gatewayStats,\n    },\n  });\n};\n\n// ── Get All Users ─────────────────────────────────────────────────────────────\nexport const getAllUsers = async (req: AuthRequest, res: Response) => {\n  const { page = 1, limit = 20, status, plan, search, role } = req.query;\n  const { take, skip } = paginate(Number(page), Number(limit));\n\n  const where: any = {};\n  if (role)   where.role   = role;\n  if (status) where.status = status;\n  if (search) where.OR = [\n    { name:  { contains: search as string, mode: \"insensitive\" } },\n    { email: { contains: search as string, mode: \"insensitive\" } },\n  ];\n\n  if (plan) where.subscription = { plan };\n\n  const [users, total] = await Promise.all([\n    await prisma.user.findMany({\n      where, take, skip,\n      include: {\n        subscription: true,\n        stores: {\n          select: { id: true, name: true, status: true, _count: { select: { orders: true } } },\n        },\n        _count: { select: { stores: true, supportTickets: true } },\n      },\n      orderBy: { createdAt: \"desc\" },\n    }),\n    await prisma.user.count({ where }),\n  ]);\n\n  // Attach total revenue per user\n  const usersWithRevenue = await Promise.all(\n    users.map(async (user) => {\n      const revenue = await prisma.payment.aggregate({\n        where: { storeId: { in: user.stores.map((s) => s.id) }, status: \"SUCCESS\" },\n        _sum:  { amount: true, platformFee: true, storeEarnings: true },\n      });\n      return {\n        ...sanitizeUser(user),\n        revenue: {\n          total:         revenue._sum.amount || 0,\n          platformFees:  revenue._sum.platformFee || 0,\n          storeEarnings: revenue._sum.storeEarnings || 0,\n        },\n      };\n    })\n  );\n\n  return res.json({\n    success: true,\n    data: usersWithRevenue,\n    pagination: { page: Number(page), limit: take, total, pages: Math.ceil(total / take) },\n  });\n};\n\n// ── Get Single User (full detail) ─────────────────────────────────────────────\nexport const getUserDetail = async (req: AuthRequest, res: Response) => {\n  const { userId } = req.params;\n  const user = await prisma.user.findUnique({\n    where: { id: userId },\n    include: {\n      subscription: true,\n      stores: {\n        include: {\n          _count:  { select: { products: true, orders: true, customers: true } },\n          payments:{ where: { status: \"SUCCESS\" }, select: { amount: true, platformFee: true, storeEarnings: true } },\n        },\n      },\n      supportTickets: { orderBy: { createdAt: \"desc\" }, take: 5 },\n      _count: { select: { stores: true, supportTickets: true } },\n    },\n  });\n  if (!user) throw new AppError(\"User not found\", 404);\n\n  const totalRevenue = await prisma.payment.aggregate({\n    where: { storeId: { in: user.stores.map((s) => s.id) }, status: \"SUCCESS\" },\n    _sum:  { amount: true, platformFee: true, storeEarnings: true },\n  });\n\n  return res.json({\n    success: true,\n    data: {\n      ...sanitizeUser(user),\n      totalRevenue: totalRevenue._sum.amount     || 0,\n      platformFees: totalRevenue._sum.platformFee|| 0,\n      payouts:      totalRevenue._sum.storeEarnings || 0,\n    },\n  });\n};\n\n// ── Update User ───────────────────────────────────────────────────────────────\nexport const updateUser = async (req: AuthRequest, res: Response) => {\n  const { userId } = req.params;\n  const schema = z.object({\n    name:          z.string().min(2).optional(),\n    email:         z.string().email().optional(),\n    phone:         z.string().optional(),\n    status:        z.enum([\"ACTIVE\",\"SUSPENDED\",\"BANNED\"]).optional(),\n    emailVerified: z.boolean().optional(),\n    twoFAEnabled:  z.boolean().optional(),\n    adminNotes:    z.string().optional(),\n    flags:         z.array(z.string()).optional(),\n    country:       z.string().optional(),\n    city:          z.string().optional(),\n    role:          z.enum([\"STORE_OWNER\",\"SUPER_ADMIN\"]).optional(),\n  });\n\n  const data = schema.parse(req.body);\n  const user = await prisma.user.update({ where: { id: userId }, data });\n\n  // Audit log\n  await (prisma.auditLog as any).create({\n    data: {\n      userId:   req.user!.userId,\n      action:   \"UPDATE_USER\",\n      entity:   \"User\",\n      entityId: userId,\n      newValues: data as any,\n    },\n  });\n\n  return res.json({ success: true, message: \"User updated\", data: sanitizeUser(user) });\n};\n\n// ── Update Subscription ───────────────────────────────────────────────────────\nexport const updateUserSubscription = async (req: AuthRequest, res: Response) => {\n  const { userId } = req.params;\n  const schema = z.object({\n    plan:            z.enum([\"STARTER\",\"PRO\",\"ADVANCED\"]),\n    status:          z.enum([\"ACTIVE\",\"CANCELLED\",\"EXPIRED\",\"PAST_DUE\"]).optional(),\n    currentPeriodEnd:z.string().optional(),\n  });\n  const data = schema.parse(req.body);\n\n  const sub = await prisma.subscription.update({\n    where: { userId },\n    data:  {\n      plan:   data.plan,\n      status: data.status,\n      ...(data.currentPeriodEnd && { currentPeriodEnd: new Date(data.currentPeriodEnd) }),\n    },\n    include: { user: { select: { email: true, name: true } } },\n  });\n\n  await (prisma.auditLog as any).create({\n    data: {\n      userId:   req.user!.userId,\n      action:   \"UPDATE_SUBSCRIPTION\",\n      entity:   \"Subscription\",\n      entityId: userId,\n      newValues: data as any,\n    },\n  });\n\n  // Send subscription email\n  try {\n    const { emailService } = await import(\"../services/email.service\");\n    const u = (sub as any).user;\n    const endDate = sub.currentPeriodEnd?.toLocaleDateString(\"en-US\", { year: \"numeric\", month: \"long\", day: \"numeric\" }) || \"N/A\";\n    if (data.status === \"ACTIVE\" || (!data.status && sub.status === \"ACTIVE\")) {\n      emailService.sendSubscriptionStarted(u.email, u.name, data.plan, endDate);\n    } else if (data.status === \"CANCELLED\") {\n      emailService.sendSubscriptionCancelled(u.email, u.name, data.plan, endDate);\n    }\n  } catch {}\n\n  return res.json({ success: true, message: \"Subscription updated\", data: sub });\n};\n\n// ── Delete User ───────────────────────────────────────────────────────────────\nexport const deleteUser = async (req: AuthRequest, res: Response) => {\n  const { userId } = req.params;\n  const user = await prisma.user.findUnique({ where: { id: userId } });\n  if (!user) throw new AppError(\"User not found\", 404);\n  if (user.role === \"SUPER_ADMIN\") throw new AppError(\"Cannot delete super admin\", 403);\n\n  await prisma.user.delete({ where: { id: userId } });\n\n  await (prisma.auditLog as any).create({\n    data: {\n      userId:   req.user!.userId,\n      action:   \"DELETE_USER\",\n      entity:   \"User\",\n      entityId: userId,\n    },\n  });\n\n  return res.json({ success: true, message: \"User deleted\" });\n};\n\n// ── Platform Settings ─────────────────────────────────────────────────────────\nexport const getSettings = async (_req: AuthRequest, res: Response) => {\n  const settings = await prisma.platformSettings.findUnique({ where: { id: \"singleton\" } });\n  return res.json({ success: true, data: settings });\n};\n\nexport const updateSettings = async (req: AuthRequest, res: Response) => {\n  const schema = z.object({\n    platformFeePercent: z.number().min(0).max(50).optional(),\n    starterPrice:       z.number().optional(),\n    proPrice:           z.number().optional(),\n    advancedPrice:      z.number().optional(),\n    maintenanceMode:    z.boolean().optional(),\n    allowRegistration:  z.boolean().optional(),\n  });\n  const data = schema.parse(req.body);\n\n  const settings = await prisma.platformSettings.update({\n    where: { id: \"singleton\" },\n    data,\n  });\n\n  await (prisma.auditLog as any).create({\n    data: {\n      userId:   req.user!.userId,\n      action:   \"UPDATE_PLATFORM_SETTINGS\",\n      entity:   \"PlatformSettings\",\n      entityId: \"singleton\",\n      newValues: data as any,\n    },\n  });\n\n  return res.json({ success: true, message: \"Settings updated\", data: settings });\n};\n\n// ── Error Logs ────────────────────────────────────────────────────────────────\nexport const getErrorLogs = async (req: AuthRequest, res: Response) => {\n  const { page = 1, limit = 20, resolved } = req.query;\n  const { take, skip } = paginate(Number(page), Number(limit));\n  const where: any = {};\n  if (resolved !== undefined) where.resolved = resolved === \"true\";\n\n  const [logs, total] = await Promise.all([\n    await prisma.errorLog.findMany({ where, take, skip, orderBy: { createdAt: \"desc\" } }),\n    await prisma.errorLog.count({ where }),\n  ]);\n\n  return res.json({\n    success: true,\n    data: logs,\n    pagination: { page: Number(page), limit: take, total, pages: Math.ceil(total / take) },\n  });\n};\n\nexport const resolveErrorLog = async (req: AuthRequest, res: Response) => {\n  const { logId } = req.params;\n  await prisma.errorLog.update({ where: { id: logId }, data: { resolved: true } });\n  return res.json({ success: true, message: \"Log resolved\" });\n};\n\n// ── Audit Logs ────────────────────────────────────────────────────────────────\nexport const getAuditLogs = async (req: AuthRequest, res: Response) => {\n  const { page = 1, limit = 20 } = req.query;\n  const { take, skip } = paginate(Number(page), Number(limit));\n\n  const [logs, total] = await Promise.all([\n    await prisma.auditLog.findMany({\n      take, skip,\n      include: { user: { select: { name: true, email: true } } },\n      orderBy: { createdAt: \"desc\" },\n    }),\n    await prisma.auditLog.count(),\n  ]);\n\n  return res.json({\n    success: true,\n    data: logs,\n    pagination: { page: Number(page), limit: take, total, pages: Math.ceil(total / take) },\n  });\n};\n\n// ── Platform Analytics ────────────────────────────────────────────────────────\nexport const getPlatformAnalytics = async (req: AuthRequest, res: Response) => {\n  const { period = \"7d\" } = req.query;\n  const days = period === \"30d\" ? 30 : period === \"90d\" ? 90 : 7;\n  const from = new Date();\n  from.setDate(from.getDate() - days);\n\n  const [revenueByDay, ordersByDay, newUsersByDay] = await Promise.all([\n    prisma.payment.groupBy({\n      by: [\"createdAt\"],\n      where: { status: \"SUCCESS\", createdAt: { gte: from } },\n      _sum: { amount: true, platformFee: true },\n    }),\n    prisma.order.groupBy({\n      by: [\"createdAt\"],\n      where: { createdAt: { gte: from } },\n      _count: { id: true },\n    }),\n    prisma.user.groupBy({\n      by: [\"createdAt\"],\n      where: { createdAt: { gte: from }, role: \"STORE_OWNER\" },\n      _count: { id: true },\n    }),\n  ]);\n\n  return res.json({\n    success: true,\n    data: { revenueByDay, ordersByDay, newUsersByDay },\n  });\n};\n\n// ── Store Management ──────────────────────────────────────────────────────────\nexport const getAllStores = async (req: AuthRequest, res: Response) => {\n  const { page=1, limit=20, search=\"\", status=\"\" } = req.query;\n  const { take, skip } = paginate(Number(page), Number(limit));\n  const where: any = {};\n  if (search) where.OR = [{ name:{contains:String(search),mode:\"insensitive\"} }, { slug:{contains:String(search),mode:\"insensitive\"} }];\n  if (status) where.status = String(status);\n\n  const [stores, total] = await Promise.all([\n    prisma.store.findMany({\n      where, take, skip, orderBy:{ createdAt:\"desc\" },\n      include: {\n        owner: { select:{ id:true, name:true, email:true, plan:true } },\n        _count: { select:{ products:true, orders:true } },\n      },\n    }),\n    prisma.store.count({ where }),\n  ]);\n\n  return res.json({ success:true, data:stores, pagination:{ page:Number(page), limit:take, total, pages:Math.ceil(total/take) } });\n};\n\nexport const updateStore = async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n  const { status, templateId, primaryColor, plan } = req.body;\n  \n  const data: any = {};\n  if (status) data.status = status;\n  if (templateId) data.templateId = templateId;\n  if (primaryColor) data.primaryColor = primaryColor;\n  \n  const store = await prisma.store.update({ where:{ id:storeId }, data });\n  return res.json({ success:true, message:\"Store updated\", data:store });\n};\n\n// ── Platform Orders ────────────────────────────────────────────────────────────\nexport const getAllOrders = async (req: AuthRequest, res: Response) => {\n  const { page=1, limit=20, search=\"\", status=\"\" } = req.query;\n  const { take, skip } = paginate(Number(page), Number(limit));\n  const where: any = {};\n  if (status) where.status = String(status);\n  if (search) where.OR = [{ orderNumber:{contains:String(search)} }, { customerEmail:{contains:String(search)} }];\n\n  const [orders, total] = await Promise.all([\n    prisma.order.findMany({\n      where, take, skip, orderBy:{ createdAt:\"desc\" },\n      include: { store:{ select:{ name:true, slug:true } } },\n    }),\n    prisma.order.count({ where }),\n  ]);\n\n  return res.json({ success:true, data:orders, pagination:{ page:Number(page), limit:take, total, pages:Math.ceil(total/take) } });\n};\n\n// ── Platform Payments ──────────────────────────────────────────────────────────\nexport const getAllPayments = async (req: AuthRequest, res: Response) => {\n  const { page=1, limit=20, gateway=\"\", status=\"\" } = req.query;\n  const { take, skip } = paginate(Number(page), Number(limit));\n  const where: any = {};\n  if (gateway) where.gateway = String(gateway);\n  if (status) where.status = String(status);\n\n  const [payments, total] = await Promise.all([\n    prisma.payment.findMany({\n      where, take, skip, orderBy:{ createdAt:\"desc\" },\n      include: { order:{ select:{ orderNumber:true, store:{ select:{ name:true } } } } },\n    }),\n    prisma.payment.count({ where }),\n  ]);\n\n  return res.json({ success:true, data:payments, pagination:{ page:Number(page), limit:take, total, pages:Math.ceil(total/take) } });\n};\n\n// ── Broadcast Message to All Users ────────────────────────────────────────────\nexport const broadcastMessage = async (req: AuthRequest, res: Response) => {\n  const { title, message, type=\"info\", targetPlan=\"\" } = req.body;\n  if (!title || !message) return res.status(400).json({ success:false, error:\"title and message required\" });\n\n  const where: any = { role:\"STORE_OWNER\" };\n  if (targetPlan) where.plan = String(targetPlan);\n\n  const users = await prisma.user.findMany({ where, select:{ id:true } });\n  \n  // Create notification for each user\n  await prisma.notification.createMany({\n    data: users.map((u:any) => ({\n      userId:  u.id,\n      title,\n      body:    message,\n      type:    type as any,\n      channel: \"IN_APP\",\n    })),\n    skipDuplicates: true,\n  });\n\n  return res.json({ success:true, message:`Broadcast sent to ${users.length} users` });\n};\n\n// ── Manual Plan Change ─────────────────────────────────────────────────────────\nexport const changeUserPlan = async (req: AuthRequest, res: Response) => {\n  const { userId } = req.params;\n  const { plan, reason } = req.body;\n  const valid = [\"FREE\",\"GROWTH\",\"PRO\",\"ENTERPRISE\"];\n  if (!valid.includes(plan)) return res.status(400).json({ success:false, error:\"Invalid plan\" });\n\n  await prisma.user.update({ where:{ id:userId }, data:{ plan } });\n  \n  // Log the action\n  await prisma.auditLog.create({\n    data: {\n      userId: (req as any).user.userId,\n      action: \"PLAN_CHANGE\",\n      resource:\"user\",\n      resourceId: userId,\n      details: { plan, reason, changedBy:(req as any).user.userId },\n    } as any,\n  });\n\n  return res.json({ success:true, message:`Plan changed to ${plan}` });\n};\n\n// ── Feature Flags ──────────────────────────────────────────────────────────────\nexport const getFeatureFlags = async (_req: AuthRequest, res: Response) => {\n  const settings = await prisma.platformSetting.findMany({ where:{ key:{ startsWith:\"feature_\" } } });\n  const flags: Record<string,boolean> = {};\n  settings.forEach((s:any) => { flags[s.key.replace(\"feature_\",\"\")] = s.value === \"true\"; });\n  return res.json({ success:true, data:flags });\n};\n\nexport const updateFeatureFlag = async (req: AuthRequest, res: Response) => {\n  const { flag, enabled } = req.body;\n  await prisma.platformSetting.upsert({\n    where:  { key:`feature_${flag}` },\n    update: { value:String(enabled) },\n    create: { key:`feature_${flag}`, value:String(enabled) },\n  });\n  return res.json({ success:true, message:\"Feature flag updated\" });\n};\n","backend/src/routes/admin.routes.ts":"import { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport {\n  getDashboardStats, getAllUsers, getUserDetail,\n  updateUser, updateUserSubscription, deleteUser,\n  getSettings, updateSettings,\n  getErrorLogs, resolveErrorLog,\n  getAuditLogs, getPlatformAnalytics,\n  getAllStores, updateStore,\n  getAllOrders, getAllPayments,\n  broadcastMessage, changeUserPlan,\n  getFeatureFlags, updateFeatureFlag,\n} from \"../controllers/admin.controller\";\n\nconst router = Router();\nrouter.use(authenticate);\n\nrouter.get (\"/dashboard\",                   getDashboardStats);\nrouter.get (\"/stats\",                       getDashboardStats);\nrouter.get (\"/analytics\",                   getPlatformAnalytics);\n\n// Users\nrouter.get (\"/users\",                       getAllUsers);\nrouter.get (\"/users/:userId\",               getUserDetail);\nrouter.patch(\"/users/:userId\",              updateUser);\nrouter.patch(\"/users/:userId/subscription\", updateUserSubscription);\nrouter.patch(\"/users/:userId/plan\",         changeUserPlan);\nrouter.delete(\"/users/:userId\",             deleteUser);\n\n// Stores\nrouter.get (\"/stores\",                      getAllStores);\nrouter.patch(\"/stores/:storeId\",            updateStore);\n\n// Orders & Payments\nrouter.get (\"/orders\",                      getAllOrders);\nrouter.get (\"/payments\",                    getAllPayments);\n\n// Platform tools\nrouter.post(\"/broadcast\",                   broadcastMessage);\nrouter.get (\"/feature-flags\",               getFeatureFlags);\nrouter.patch(\"/feature-flags\",              updateFeatureFlag);\n\n// Settings & Logs\nrouter.get (\"/settings\",                    getSettings);\nrouter.patch(\"/settings\",                   updateSettings);\nrouter.get (\"/error-logs\",                  getErrorLogs);\nrouter.patch(\"/error-logs/:logId/resolve\",  resolveErrorLog);\nrouter.get (\"/audit-logs\",                  getAuditLogs);\n\nexport default router;\n","frontend/src/app/admin/layout.tsx":"\"use client\";\nimport { useEffect, useState } from \"react\";\nimport { useRouter, usePathname } from \"next/navigation\";\nimport Link from \"next/link\";\nimport { useAuthStore } from \"../../store/auth.store\";\nimport {\n  LayoutDashboard, Users, Store, ShoppingCart, CreditCard,\n  BarChart2, Settings, AlertCircle, Shield, Bell, LogOut,\n  Menu, X, Zap, Globe, Megaphone, Flag, ChevronRight,\n} from \"lucide-react\";\n\nconst V = { bg:\"#0A0714\", card:\"rgba(255,255,255,0.03)\", border:\"rgba(255,255,255,0.07)\", text:\"rgba(255,255,255,0.9)\", muted:\"rgba(255,255,255,0.4)\", accent:\"#6B35E8\" };\n\nconst NAV = [\n  { section: null, items: [\n    { href:\"/admin\",           icon:LayoutDashboard, label:\"Overview\",    exact:true },\n  ]},\n  { section:\"PLATFORM\", items: [\n    { href:\"/admin/users\",     icon:Users,           label:\"Users\"       },\n    { href:\"/admin/stores\",    icon:Store,           label:\"Stores\"      },\n    { href:\"/admin/orders\",    icon:ShoppingCart,    label:\"Orders\"      },\n    { href:\"/admin/payments\",  icon:CreditCard,      label:\"Payments\"    },\n  ]},\n  { section:\"INSIGHTS\", items: [\n    { href:\"/admin/analytics\", icon:BarChart2,       label:\"Analytics\"   },\n    { href:\"/admin/audit-logs\",icon:Shield,          label:\"Audit Logs\"  },\n    { href:\"/admin/error-logs\",icon:AlertCircle,     label:\"Error Logs\"  },\n  ]},\n  { section:\"TOOLS\", items: [\n    { href:\"/admin/broadcast\", icon:Megaphone,       label:\"Broadcast\"   },\n    { href:\"/admin/flags\",     icon:Flag,            label:\"Feature Flags\"},\n    { href:\"/admin/support\",   icon:Bell,            label:\"Support\"     },\n    { href:\"/admin/settings\",  icon:Settings,        label:\"Settings\"    },\n  ]},\n];\n\nexport default function AdminLayout({ children }: { children: React.ReactNode }) {\n  const { user, isHydrated, logout } = useAuthStore();\n  const router   = useRouter();\n  const pathname = usePathname();\n  const [mobileOpen, setMobileOpen] = useState(false);\n\n  useEffect(() => {\n    if (!isHydrated) return;\n    if (!user) { router.replace(\"/auth/login\"); return; }\n    if (user.role !== \"SUPER_ADMIN\") router.replace(\"/dashboard\");\n  }, [user, isHydrated]);\n\n  if (!isHydrated || !user || user.role !== \"SUPER_ADMIN\") return (\n    <div style={{ minHeight:\"100vh\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", background:V.bg }}>\n      <div style={{ width:32, height:32, borderRadius:\"50%\", border:`3px solid rgba(107,53,232,0.15)`, borderTopColor:V.accent, animation:\"spin 0.7s linear infinite\" }}/>\n      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>\n    </div>\n  );\n\n  const isActive = (n: any) => n.exact ? pathname === n.href : pathname.startsWith(n.href);\n\n  const Sidebar = () => (\n    <div style={{ display:\"flex\", flexDirection:\"column\", height:\"100%\", overflowY:\"auto\" }}>\n      {/* Logo */}\n      <div style={{ padding:\"20px 16px 16px\", borderBottom:`1px solid ${V.border}` }}>\n        <Link href=\"/admin\" style={{ display:\"flex\", alignItems:\"center\", gap:10, textDecoration:\"none\" }}>\n          <div style={{ width:34, height:34, borderRadius:10, background:\"linear-gradient(145deg,#2D1B69,#0D0625)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\"/></svg>\n          </div>\n          <div>\n            <p style={{ fontSize:14, fontWeight:900, color:\"#fff\", margin:0, letterSpacing:\"-0.03em\" }}>Drop<span style={{ color:V.accent }}>OS</span></p>\n            <p style={{ fontSize:9, color:\"rgba(255,255,255,0.3)\", margin:0, fontWeight:700, letterSpacing:\"0.1em\" }}>SUPER ADMIN</p>\n          </div>\n        </Link>\n      </div>\n\n      {/* Nav */}\n      <nav style={{ flex:1, padding:\"12px 8px\" }}>\n        {NAV.map((group, gi) => (\n          <div key={gi} style={{ marginBottom:8 }}>\n            {group.section && (\n              <p style={{ fontSize:9, fontWeight:800, letterSpacing:\"0.12em\", color:\"rgba(255,255,255,0.2)\", textTransform:\"uppercase\", padding:\"6px 10px 3px\", margin:0 }}>\n                {group.section}\n              </p>\n            )}\n            {group.items.map(n => {\n              const active = isActive(n);\n              const Icon   = n.icon;\n              return (\n                <Link key={n.href} href={n.href} onClick={() => setMobileOpen(false)}\n                  style={{ display:\"flex\", alignItems:\"center\", gap:9, padding:\"8px 10px\", borderRadius:10, marginBottom:1, textDecoration:\"none\", background:active?\"rgba(107,53,232,0.12)\":\"transparent\", border:`1px solid ${active?\"rgba(107,53,232,0.2)\":\"transparent\"}`, transition:\"all 0.12s\" }}>\n                  <Icon size={14} color={active?\"#A78BFA\":\"rgba(255,255,255,0.35)\"}/>\n                  <span style={{ fontSize:13, fontWeight:active?700:500, color:active?\"#fff\":\"rgba(255,255,255,0.5)\", flex:1 }}>{n.label}</span>\n                  {active && <ChevronRight size={11} color=\"rgba(167,139,250,0.6)\"/>}\n                </Link>\n              );\n            })}\n          </div>\n        ))}\n      </nav>\n\n      {/* Footer */}\n      <div style={{ padding:\"12px 10px\", borderTop:`1px solid ${V.border}` }}>\n        <div style={{ display:\"flex\", alignItems:\"center\", gap:8, padding:\"8px\", borderRadius:10, background:\"rgba(255,255,255,0.03)\", marginBottom:8 }}>\n          <div style={{ width:28, height:28, borderRadius:8, background:\"linear-gradient(145deg,#2D1B69,#6B35E8)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", fontSize:12, fontWeight:900, color:\"#fff\", flexShrink:0 }}>\n            {user.name?.charAt(0)||\"A\"}\n          </div>\n          <div style={{ flex:1, minWidth:0 }}>\n            <p style={{ fontSize:12, fontWeight:700, color:\"rgba(255,255,255,0.8)\", margin:0, overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>{user.name}</p>\n            <p style={{ fontSize:10, color:\"rgba(255,255,255,0.3)\", margin:0 }}>Super Admin</p>\n          </div>\n        </div>\n        <div style={{ display:\"flex\", gap:6 }}>\n          <Link href=\"/dashboard\" style={{ flex:1, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:4, padding:\"6px\", borderRadius:8, background:\"rgba(255,255,255,0.04)\", border:`1px solid ${V.border}`, textDecoration:\"none\", fontSize:11, fontWeight:600, color:\"rgba(255,255,255,0.4)\" }}>\n            <Globe size={10}/> Store\n          </Link>\n          <button onClick={() => { logout(); router.push(\"/auth/login\"); }}\n            style={{ flex:1, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:4, padding:\"6px\", borderRadius:8, background:\"rgba(239,68,68,0.07)\", border:\"1px solid rgba(239,68,68,0.12)\", cursor:\"pointer\", fontSize:11, fontWeight:600, color:\"rgba(239,68,68,0.7)\", fontFamily:\"inherit\" }}>\n            <LogOut size={10}/> Out\n          </button>\n        </div>\n      </div>\n    </div>\n  );\n\n  return (\n    <div style={{ minHeight:\"100vh\", background:V.bg, fontFamily:\"'Plus Jakarta Sans',system-ui,sans-serif\", display:\"flex\" }}>\n      <style>{`\n        @import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&display=swap');\n        * { box-sizing:border-box; margin:0; }\n        :root { --accent:#6B35E8; --green:#10B981; --amber:#F59E0B; --red:#EF4444; --cyan:#06B6D4; }\n        @keyframes spin{to{transform:rotate(360deg)}}\n        @media(min-width:1024px){ .adm-sidebar{display:flex!important} .adm-topbar{display:none!important} }\n        @media(max-width:1023px){ .adm-sidebar{display:none!important} .adm-topbar{display:flex!important} }\n      `}</style>\n\n      {/* Desktop sidebar */}\n      <aside className=\"adm-sidebar\" style={{ width:210, flexShrink:0, background:\"rgba(255,255,255,0.015)\", borderRight:`1px solid ${V.border}`, height:\"100vh\", position:\"sticky\", top:0, flexDirection:\"column\" }}>\n        <Sidebar/>\n      </aside>\n\n      {/* Mobile overlay */}\n      {mobileOpen && (\n        <div style={{ position:\"fixed\", inset:0, zIndex:50, display:\"flex\" }}>\n          <div onClick={() => setMobileOpen(false)} style={{ flex:1, background:\"rgba(0,0,0,0.6)\", backdropFilter:\"blur(4px)\" }}/>\n          <div style={{ width:220, background:\"#0d0a1a\", borderLeft:`1px solid ${V.border}`, height:\"100%\", display:\"flex\", flexDirection:\"column\" }}>\n            <Sidebar/>\n          </div>\n        </div>\n      )}\n\n      {/* Main */}\n      <div style={{ flex:1, display:\"flex\", flexDirection:\"column\", minWidth:0 }}>\n        {/* Mobile topbar */}\n        <div className=\"adm-topbar\" style={{ alignItems:\"center\", justifyContent:\"space-between\", padding:\"12px 16px\", borderBottom:`1px solid ${V.border}`, position:\"sticky\", top:0, background:\"rgba(10,7,20,0.95)\", backdropFilter:\"blur(10px)\", zIndex:30 }}>\n          <div style={{ display:\"flex\", alignItems:\"center\", gap:10 }}>\n            <div style={{ width:28, height:28, borderRadius:8, background:\"linear-gradient(145deg,#2D1B69,#0D0625)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n              <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\"/></svg>\n            </div>\n            <span style={{ fontSize:14, fontWeight:900, color:\"#fff\" }}>Admin</span>\n          </div>\n          <button onClick={() => setMobileOpen(o => !o)} style={{ background:\"none\", border:\"none\", cursor:\"pointer\", color:\"rgba(255,255,255,0.5)\", padding:4 }}>\n            {mobileOpen ? <X size={18}/> : <Menu size={18}/>}\n          </button>\n        </div>\n\n        {/* Content */}\n        <main style={{ flex:1, padding:\"clamp(16px,2.5vw,28px)\", overflowY:\"auto\" }}>\n          {children}\n        </main>\n      </div>\n    </div>\n  );\n}\n","frontend/src/app/admin/stores/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\nimport { motion } from \"framer-motion\";\nimport { Search, Store, ExternalLink, Ban, CheckCircle } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\n\nconst V = { accent:\"#6B35E8\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\" };\nconst t = { border:\"rgba(255,255,255,0.07)\", text:\"rgba(255,255,255,0.9)\", muted:\"rgba(255,255,255,0.4)\" };\n\nexport default function AdminStoresPage() {\n  const qc = useQueryClient();\n  const [search, setSearch] = useState(\"\"); const [page, setPage] = useState(1);\n\n  const { data, isLoading } = useQuery<any>({\n    queryKey: [\"admin-stores\", page, search],\n    queryFn: () => adminAPI.get(\"/admin/stores\", { params:{ page, limit:20, search } }).then((r:any) => r.data),\n  });\n\n  const updateMut = useMutation({\n    mutationFn: ({ id, data }: any) => adminAPI.patch(`/admin/stores/${id}`, data),\n    onSuccess: () => { toast.success(\"Updated\"); qc.invalidateQueries({ queryKey:[\"admin-stores\"] }); },\n  });\n\n  const stores = data?.data || []; const meta = data?.pagination || { total:0, pages:1 };\n\n  return (\n    <div>\n      <motion.div initial={{ opacity:0,y:-8 }} animate={{ opacity:1,y:0 }} style={{ marginBottom:20 }}>\n        <h1 style={{ fontSize:22, fontWeight:900, color:t.text, margin:\"0 0 4px\", letterSpacing:\"-0.04em\" }}>Stores</h1>\n        <p style={{ fontSize:13, color:t.muted }}>{meta.total?.toLocaleString()||0} stores on the platform</p>\n      </motion.div>\n\n      <div style={{ position:\"relative\", marginBottom:14 }}>\n        <Search size={13} style={{ position:\"absolute\", left:12, top:\"50%\", transform:\"translateY(-50%)\", color:t.muted }}/>\n        <input value={search} onChange={e => { setSearch(e.target.value); setPage(1); }} placeholder=\"Search by name or slug...\"\n          style={{ width:\"100%\", padding:\"9px 12px 9px 34px\", borderRadius:10, border:`1px solid ${t.border}`, background:\"rgba(255,255,255,0.04)\", color:t.text, fontSize:13, fontFamily:\"inherit\", outline:\"none\" }}/>\n      </div>\n\n      <div style={{ borderRadius:16, border:`1px solid ${t.border}`, overflow:\"hidden\" }}>\n        <table style={{ width:\"100%\", borderCollapse:\"collapse\" }}>\n          <thead>\n            <tr style={{ background:\"rgba(255,255,255,0.02)\" }}>\n              {[\"Store\",\"Owner\",\"Plan\",\"Products\",\"Orders\",\"Status\",\"\"].map(h => (\n                <th key={h} style={{ padding:\"10px 14px\", textAlign:\"left\", fontSize:10, fontWeight:700, letterSpacing:\"0.08em\", color:\"rgba(255,255,255,0.25)\", textTransform:\"uppercase\", borderBottom:`1px solid ${t.border}` }}>{h}</th>\n              ))}\n            </tr>\n          </thead>\n          <tbody>\n            {isLoading ? (\n              <tr><td colSpan={7} style={{ padding:40, textAlign:\"center\", color:t.muted }}>Loading...</td></tr>\n            ) : stores.map((s: any, i: number) => (\n              <tr key={s.id} style={{ borderBottom:`1px solid rgba(255,255,255,0.04)` }}>\n                <td style={{ padding:\"12px 14px\" }}>\n                  <div style={{ display:\"flex\", alignItems:\"center\", gap:8 }}>\n                    <div style={{ width:28, height:28, borderRadius:7, background:`${s.primaryColor||V.accent}18`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                      <Store size={12} color={s.primaryColor||V.accent}/>\n                    </div>\n                    <div>\n                      <p style={{ fontSize:13, fontWeight:700, color:t.text, margin:0 }}>{s.name}</p>\n                      <p style={{ fontSize:10, color:t.muted, margin:0 }}>/{s.slug}</p>\n                    </div>\n                  </div>\n                </td>\n                <td style={{ padding:\"12px 14px\" }}>\n                  <p style={{ fontSize:12, color:t.text, margin:0 }}>{s.owner?.name}</p>\n                  <p style={{ fontSize:10, color:t.muted, margin:0 }}>{s.owner?.email}</p>\n                </td>\n                <td style={{ padding:\"12px 14px\" }}>\n                  <span style={{ fontSize:11, fontWeight:700, padding:\"2px 8px\", borderRadius:99, background:\"rgba(107,53,232,0.1)\", color:V.accent }}>{s.owner?.plan||\"FREE\"}</span>\n                </td>\n                <td style={{ padding:\"12px 14px\", fontSize:13, fontWeight:700, color:t.text }}>{s._count?.products||0}</td>\n                <td style={{ padding:\"12px 14px\", fontSize:13, fontWeight:700, color:t.text }}>{s._count?.orders||0}</td>\n                <td style={{ padding:\"12px 14px\" }}>\n                  <span style={{ fontSize:11, fontWeight:700, padding:\"3px 10px\", borderRadius:99, background:s.status===\"SUSPENDED\"?\"rgba(239,68,68,0.1)\":\"rgba(16,185,129,0.1)\", color:s.status===\"SUSPENDED\"?V.red:V.green }}>\n                    {s.status||\"ACTIVE\"}\n                  </span>\n                </td>\n                <td style={{ padding:\"12px 14px\" }}>\n                  <div style={{ display:\"flex\", gap:6 }}>\n                    <a href={`/store/${s.slug}`} target=\"_blank\" rel=\"noreferrer\"\n                      style={{ padding:\"4px 7px\", borderRadius:6, background:\"rgba(255,255,255,0.05)\", border:`1px solid ${t.border}`, color:t.muted, textDecoration:\"none\", display:\"flex\", alignItems:\"center\" }}>\n                      <ExternalLink size={11}/>\n                    </a>\n                    <button onClick={() => updateMut.mutate({ id:s.id, data:{ status:s.status===\"SUSPENDED\"?\"ACTIVE\":\"SUSPENDED\" } })}\n                      style={{ padding:\"4px 7px\", borderRadius:6, background:s.status===\"SUSPENDED\"?\"rgba(16,185,129,0.1)\":\"rgba(239,68,68,0.07)\", border:`1px solid ${s.status===\"SUSPENDED\"?\"rgba(16,185,129,0.2)\":\"rgba(239,68,68,0.15)\"}`, color:s.status===\"SUSPENDED\"?V.green:V.red, cursor:\"pointer\", display:\"flex\", alignItems:\"center\" }}>\n                      {s.status===\"SUSPENDED\" ? <CheckCircle size={11}/> : <Ban size={11}/>}\n                    </button>\n                  </div>\n                </td>\n              </tr>\n            ))}\n          </tbody>\n        </table>\n      </div>\n      <p style={{ fontSize:12, color:t.muted, marginTop:10 }}>{meta.total} total stores · Page {page} of {meta.pages}</p>\n    </div>\n  );\n}\n","frontend/src/app/admin/orders/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\nimport { motion } from \"framer-motion\";\nimport { Search } from \"lucide-react\";\n\nconst V = { accent:\"#6B35E8\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\", cyan:\"#06B6D4\" };\nconst t = { border:\"rgba(255,255,255,0.07)\", text:\"rgba(255,255,255,0.9)\", muted:\"rgba(255,255,255,0.4)\" };\n\nconst STATUS_COLOR: Record<string,string> = { PENDING:V.amber, PROCESSING:V.cyan, SHIPPED:V.accent, DELIVERED:V.green, CANCELLED:V.red, REFUNDED:\"rgba(255,255,255,0.3)\" };\n\nfunction fmtNGN(n: number) { return `₦${Number(n||0).toLocaleString()}`; }\n\nexport default function AdminOrdersPage() {\n  const [search, setSearch] = useState(\"\"); const [status, setStatus] = useState(\"\"); const [page, setPage] = useState(1);\n\n  const { data, isLoading } = useQuery<any>({\n    queryKey: [\"admin-orders\", page, search, status],\n    queryFn: () => adminAPI.get(\"/admin/orders\", { params:{ page, limit:25, search, status } }).then((r:any) => r.data),\n  });\n\n  const orders = data?.data || []; const meta = data?.pagination || { total:0, pages:1 };\n\n  return (\n    <div>\n      <motion.div initial={{ opacity:0,y:-8 }} animate={{ opacity:1,y:0 }} style={{ marginBottom:20 }}>\n        <h1 style={{ fontSize:22, fontWeight:900, color:t.text, margin:\"0 0 4px\", letterSpacing:\"-0.04em\" }}>All Orders</h1>\n        <p style={{ fontSize:13, color:t.muted }}>{meta.total?.toLocaleString()||0} orders across all stores</p>\n      </motion.div>\n\n      <div style={{ display:\"flex\", gap:10, marginBottom:14, flexWrap:\"wrap\" }}>\n        <div style={{ flex:1, minWidth:200, position:\"relative\" }}>\n          <Search size={13} style={{ position:\"absolute\", left:12, top:\"50%\", transform:\"translateY(-50%)\", color:t.muted }}/>\n          <input value={search} onChange={e => { setSearch(e.target.value); setPage(1); }} placeholder=\"Search by order # or email...\"\n            style={{ width:\"100%\", padding:\"9px 12px 9px 34px\", borderRadius:10, border:`1px solid ${t.border}`, background:\"rgba(255,255,255,0.04)\", color:t.text, fontSize:13, fontFamily:\"inherit\", outline:\"none\" }}/>\n        </div>\n        <select value={status} onChange={e => { setStatus(e.target.value); setPage(1); }}\n          style={{ padding:\"9px 14px\", borderRadius:10, border:`1px solid ${t.border}`, background:\"rgba(255,255,255,0.04)\", color:t.text, fontSize:13, fontFamily:\"inherit\", outline:\"none\" }}>\n          <option value=\"\">All statuses</option>\n          {[\"PENDING\",\"PROCESSING\",\"SHIPPED\",\"DELIVERED\",\"CANCELLED\",\"REFUNDED\"].map(s => <option key={s} value={s}>{s}</option>)}\n        </select>\n      </div>\n\n      <div style={{ borderRadius:16, border:`1px solid ${t.border}`, overflow:\"hidden\" }}>\n        <table style={{ width:\"100%\", borderCollapse:\"collapse\" }}>\n          <thead>\n            <tr style={{ background:\"rgba(255,255,255,0.02)\" }}>\n              {[\"Order #\",\"Store\",\"Customer\",\"Total\",\"Status\",\"Date\"].map(h => (\n                <th key={h} style={{ padding:\"10px 14px\", textAlign:\"left\", fontSize:10, fontWeight:700, letterSpacing:\"0.08em\", color:\"rgba(255,255,255,0.25)\", textTransform:\"uppercase\", borderBottom:`1px solid ${t.border}` }}>{h}</th>\n              ))}\n            </tr>\n          </thead>\n          <tbody>\n            {isLoading ? <tr><td colSpan={6} style={{ padding:40, textAlign:\"center\", color:t.muted }}>Loading...</td></tr>\n            : orders.length === 0 ? <tr><td colSpan={6} style={{ padding:40, textAlign:\"center\", color:t.muted }}>No orders</td></tr>\n            : orders.map((o: any) => (\n              <tr key={o.id} style={{ borderBottom:`1px solid rgba(255,255,255,0.03)` }}>\n                <td style={{ padding:\"11px 14px\" }}>\n                  <span style={{ fontSize:13, fontWeight:700, color:\"#A78BFA\", fontFamily:\"monospace\" }}>#{o.orderNumber}</span>\n                </td>\n                <td style={{ padding:\"11px 14px\", fontSize:12, color:t.text }}>{o.store?.name||\"—\"}</td>\n                <td style={{ padding:\"11px 14px\" }}>\n                  <p style={{ fontSize:12, color:t.text, margin:0 }}>{o.customerName||\"—\"}</p>\n                  <p style={{ fontSize:10, color:t.muted, margin:0 }}>{o.customerEmail}</p>\n                </td>\n                <td style={{ padding:\"11px 14px\", fontSize:13, fontWeight:700, color:t.text }}>{fmtNGN(o.total)}</td>\n                <td style={{ padding:\"11px 14px\" }}>\n                  <span style={{ fontSize:11, fontWeight:700, padding:\"3px 9px\", borderRadius:99, background:`${STATUS_COLOR[o.status]||V.amber}12`, color:STATUS_COLOR[o.status]||V.amber }}>\n                    {o.status}\n                  </span>\n                </td>\n                <td style={{ padding:\"11px 14px\", fontSize:11, color:t.muted }}>\n                  {new Date(o.createdAt).toLocaleDateString(\"en-NG\", { day:\"numeric\", month:\"short\", year:\"2-digit\" })}\n                </td>\n              </tr>\n            ))}\n          </tbody>\n        </table>\n      </div>\n\n      <div style={{ display:\"flex\", justifyContent:\"space-between\", alignItems:\"center\", marginTop:12 }}>\n        <span style={{ fontSize:12, color:t.muted }}>Page {page} of {meta.pages}</span>\n        <div style={{ display:\"flex\", gap:6 }}>\n          {page > 1 && <button onClick={() => setPage(p=>p-1)} style={{ padding:\"6px 12px\", borderRadius:8, border:`1px solid ${t.border}`, background:\"transparent\", color:t.muted, cursor:\"pointer\", fontSize:12 }}>Prev</button>}\n          {page < meta.pages && <button onClick={() => setPage(p=>p+1)} style={{ padding:\"6px 12px\", borderRadius:8, border:`1px solid ${t.border}`, background:\"transparent\", color:t.muted, cursor:\"pointer\", fontSize:12 }}>Next</button>}\n        </div>\n      </div>\n    </div>\n  );\n}\n","frontend/src/app/admin/broadcast/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useMutation } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\nimport { motion } from \"framer-motion\";\nimport { Megaphone, Send, Check } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\n\nconst V = { accent:\"#6B35E8\", green:\"#10B981\" };\nconst t = { card:\"rgba(255,255,255,0.03)\", border:\"rgba(255,255,255,0.07)\", text:\"rgba(255,255,255,0.9)\", muted:\"rgba(255,255,255,0.4)\", input:\"rgba(255,255,255,0.05)\" };\n\nconst inp = { width:\"100%\", padding:\"11px 14px\", borderRadius:12, border:`1px solid rgba(255,255,255,0.09)`, background:\"rgba(255,255,255,0.05)\", color:\"rgba(255,255,255,0.9)\", fontSize:13, fontFamily:\"inherit\", outline:\"none\" };\n\nexport default function AdminBroadcastPage() {\n  const [form, setForm] = useState({ title:\"\", message:\"\", type:\"info\", targetPlan:\"\" });\n  const [sent, setSent] = useState(false);\n\n  const sendMut = useMutation({\n    mutationFn: () => adminAPI.post(\"/admin/broadcast\", form),\n    onSuccess: (res: any) => {\n      toast.success(res.data?.message || \"Broadcast sent!\");\n      setSent(true);\n      setTimeout(() => { setSent(false); setForm({ title:\"\", message:\"\", type:\"info\", targetPlan:\"\" }); }, 3000);\n    },\n    onError: () => toast.error(\"Failed to send broadcast\"),\n  });\n\n  return (\n    <div style={{ maxWidth:680 }}>\n      <motion.div initial={{ opacity:0,y:-8 }} animate={{ opacity:1,y:0 }} style={{ marginBottom:24 }}>\n        <h1 style={{ fontSize:22, fontWeight:900, color:t.text, margin:\"0 0 4px\", letterSpacing:\"-0.04em\" }}>Broadcast Message</h1>\n        <p style={{ fontSize:13, color:t.muted }}>Send an in-app notification to all or selected users</p>\n      </motion.div>\n\n      <motion.div initial={{ opacity:0,y:12 }} animate={{ opacity:1,y:0 }} transition={{ delay:0.1 }}\n        style={{ background:t.card, borderRadius:20, padding:28, border:`1px solid ${t.border}`, display:\"flex\", flexDirection:\"column\", gap:16 }}>\n\n        <div>\n          <label style={{ fontSize:12, fontWeight:700, color:t.muted, display:\"block\", marginBottom:7 }}>Message type</label>\n          <div style={{ display:\"flex\", gap:8 }}>\n            {[\"info\",\"success\",\"warning\",\"error\"].map(tp => (\n              <button key={tp} onClick={() => setForm(f => ({ ...f, type:tp }))}\n                style={{ padding:\"7px 16px\", borderRadius:9, border:`1px solid ${form.type===tp?\"rgba(107,53,232,0.4)\":\"rgba(255,255,255,0.08)\"}`, background:form.type===tp?\"rgba(107,53,232,0.1)\":\"transparent\", color:form.type===tp?\"#A78BFA\":t.muted, cursor:\"pointer\", fontSize:12, fontWeight:700, fontFamily:\"inherit\", textTransform:\"capitalize\" }}>\n                {tp}\n              </button>\n            ))}\n          </div>\n        </div>\n\n        <div>\n          <label style={{ fontSize:12, fontWeight:700, color:t.muted, display:\"block\", marginBottom:7 }}>Target audience</label>\n          <select value={form.targetPlan} onChange={e => setForm(f => ({ ...f, targetPlan:e.target.value }))}\n            style={{ ...inp }}>\n            <option value=\"\">All users</option>\n            <option value=\"FREE\">Free plan only</option>\n            <option value=\"GROWTH\">Growth plan only</option>\n            <option value=\"PRO\">Pro plan only</option>\n          </select>\n        </div>\n\n        <div>\n          <label style={{ fontSize:12, fontWeight:700, color:t.muted, display:\"block\", marginBottom:7 }}>Title</label>\n          <input value={form.title} onChange={e => setForm(f => ({ ...f, title:e.target.value }))}\n            placeholder=\"e.g. New feature available!\" style={{ ...inp }}/>\n        </div>\n\n        <div>\n          <label style={{ fontSize:12, fontWeight:700, color:t.muted, display:\"block\", marginBottom:7 }}>Message</label>\n          <textarea value={form.message} onChange={e => setForm(f => ({ ...f, message:e.target.value }))}\n            placeholder=\"Write your message to users...\"\n            rows={5} style={{ ...inp, resize:\"vertical\" as any }}/>\n          <p style={{ fontSize:11, color:t.muted, marginTop:4, textAlign:\"right\" }}>{form.message.length} chars</p>\n        </div>\n\n        {/* Preview */}\n        {form.title && form.message && (\n          <div style={{ padding:16, borderRadius:14, background:\"rgba(107,53,232,0.06)\", border:\"1px solid rgba(107,53,232,0.15)\" }}>\n            <p style={{ fontSize:11, fontWeight:700, color:\"rgba(167,139,250,0.6)\", marginBottom:8, textTransform:\"uppercase\", letterSpacing:\"0.08em\" }}>Preview</p>\n            <div style={{ display:\"flex\", gap:10 }}>\n              <div style={{ width:36, height:36, borderRadius:10, background:\"linear-gradient(145deg,#2D1B69,#0D0625)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", flexShrink:0 }}>\n                <Megaphone size={14} color=\"#C4B5FD\"/>\n              </div>\n              <div>\n                <p style={{ fontSize:13, fontWeight:700, color:t.text, margin:\"0 0 3px\" }}>{form.title}</p>\n                <p style={{ fontSize:12, color:t.muted, margin:0, lineHeight:1.5 }}>{form.message}</p>\n              </div>\n            </div>\n          </div>\n        )}\n\n        <button onClick={() => sendMut.mutate()} disabled={!form.title || !form.message || sendMut.isPending}\n          style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:8, padding:\"14px 0\", borderRadius:12, border:\"none\", cursor:\"pointer\", background:sent?\"rgba(16,185,129,0.15)\":V.accent, color:\"#fff\", fontSize:14, fontWeight:700, fontFamily:\"inherit\", opacity:(!form.title||!form.message)?0.5:1, transition:\"all 0.2s\", boxShadow:sent?\"none\":\"0 4px 20px rgba(107,53,232,0.25)\" }}>\n          {sent ? <><Check size={16}/> Sent!</> : sendMut.isPending ? \"Sending...\" : <><Send size={14}/> Send broadcast</>}\n        </button>\n      </motion.div>\n\n      {/* Tips */}\n      <div style={{ marginTop:16, padding:\"14px 18px\", borderRadius:14, background:\"rgba(255,255,255,0.02)\", border:`1px solid ${t.border}` }}>\n        <p style={{ fontSize:12, color:t.muted, lineHeight:1.6, margin:0 }}>\n          💡 Broadcasts appear as in-app notifications for all targeted users when they next open their dashboard. Use for feature announcements, maintenance notices, or promotional messages.\n        </p>\n      </div>\n    </div>\n  );\n}\n","frontend/src/app/admin/flags/page.tsx":"\"use client\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\nimport { motion } from \"framer-motion\";\nimport toast from \"react-hot-toast\";\nimport { Flag, RefreshCw } from \"lucide-react\";\n\nconst V = { accent:\"#6B35E8\", green:\"#10B981\" };\nconst t = { card:\"rgba(255,255,255,0.03)\", border:\"rgba(255,255,255,0.07)\", text:\"rgba(255,255,255,0.9)\", muted:\"rgba(255,255,255,0.4)\" };\n\nconst FLAG_DEFS = [\n  { key:\"kiro_enabled\",          label:\"KIRO AI\",                  desc:\"Enable/disable KIRO AI across all dashboards\" },\n  { key:\"store_generator\",       label:\"AI Store Generator\",        desc:\"Merchants can generate store identity with KIRO\" },\n  { key:\"virtual_accounts\",      label:\"Virtual Bank Accounts\",     desc:\"Paystack DVA feature (requires CAC + verified account)\" },\n  { key:\"delivery_booking\",      label:\"Delivery Booking\",          desc:\"GIG Logistics + Kwik rider booking\" },\n  { key:\"affiliate_program\",     label:\"Affiliate Programme\",       desc:\"20% referral commissions for Pro users\" },\n  { key:\"tiktok_shop_sync\",      label:\"TikTok Shop Sync\",          desc:\"Auto-sync products to TikTok Shop\" },\n  { key:\"competitor_spy\",        label:\"Competitor Spy\",            desc:\"AI-powered competitor product research\" },\n  { key:\"beta_templates\",        label:\"Beta Templates\",            desc:\"Show experimental store templates to all users\" },\n  { key:\"maintenance_mode\",      label:\"Maintenance Mode\",          desc:\"Show maintenance banner on all merchant storefronts\" },\n  { key:\"new_user_registration\", label:\"New Registrations\",         desc:\"Allow new users to sign up (disable to pause growth)\" },\n];\n\nexport default function AdminFlagsPage() {\n  const qc = useQueryClient();\n\n  const { data:flags={}, isLoading } = useQuery<any>({\n    queryKey: [\"admin-flags\"],\n    queryFn: () => adminAPI.get(\"/admin/feature-flags\").then((r:any) => r.data.data || {}),\n  });\n\n  const updateMut = useMutation({\n    mutationFn: ({ flag, enabled }: any) => adminAPI.patch(\"/admin/feature-flags\", { flag, enabled }),\n    onSuccess: (_, vars) => {\n      toast.success(`${vars.flag} ${vars.enabled ? \"enabled\" : \"disabled\"}`);\n      qc.invalidateQueries({ queryKey:[\"admin-flags\"] });\n    },\n    onError: () => toast.error(\"Update failed\"),\n  });\n\n  return (\n    <div style={{ maxWidth:680 }}>\n      <motion.div initial={{ opacity:0,y:-8 }} animate={{ opacity:1,y:0 }} style={{ marginBottom:24 }}>\n        <h1 style={{ fontSize:22, fontWeight:900, color:t.text, margin:\"0 0 4px\", letterSpacing:\"-0.04em\" }}>Feature Flags</h1>\n        <p style={{ fontSize:13, color:t.muted }}>Turn features on/off across the entire platform instantly</p>\n      </motion.div>\n\n      <div style={{ background:t.card, borderRadius:20, border:`1px solid ${t.border}`, overflow:\"hidden\" }}>\n        {FLAG_DEFS.map((flag, i) => {\n          const enabled = flags[flag.key] === true || flags[flag.key] === \"true\";\n          return (\n            <motion.div key={flag.key} initial={{ opacity:0 }} animate={{ opacity:1 }} transition={{ delay:i*0.04 }}\n              style={{ display:\"flex\", alignItems:\"center\", gap:16, padding:\"16px 20px\", borderBottom:i<FLAG_DEFS.length-1?`1px solid rgba(255,255,255,0.04)`:\"none\" }}>\n              <div style={{ width:34, height:34, borderRadius:10, background:enabled?\"rgba(16,185,129,0.1)\":\"rgba(255,255,255,0.04)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", flexShrink:0, transition:\"background 0.2s\" }}>\n                <Flag size={14} color={enabled?V.green:\"rgba(255,255,255,0.25)\"}/>\n              </div>\n              <div style={{ flex:1 }}>\n                <p style={{ fontSize:13, fontWeight:700, color:t.text, margin:0 }}>{flag.label}</p>\n                <p style={{ fontSize:11, color:t.muted, margin:\"2px 0 0\", lineHeight:1.4 }}>{flag.desc}</p>\n              </div>\n              {updateMut.isPending ? (\n                <RefreshCw size={14} color={t.muted} style={{ animation:\"spin 0.7s linear infinite\", flexShrink:0 }}/>\n              ) : (\n                <button onClick={() => updateMut.mutate({ flag:flag.key, enabled:!enabled })}\n                  style={{ width:48, height:26, borderRadius:13, border:\"none\", cursor:\"pointer\", background:enabled?V.accent:\"rgba(255,255,255,0.1)\", position:\"relative\", transition:\"background 0.2s\", padding:0, flexShrink:0 }}>\n                  <div style={{ position:\"absolute\", top:3, left:enabled?25:3, width:20, height:20, borderRadius:\"50%\", background:\"#fff\", transition:\"left 0.2s\", boxShadow:\"0 1px 4px rgba(0,0,0,0.3)\" }}/>\n                </button>\n              )}\n            </motion.div>\n          );\n        })}\n      </div>\n\n      <style>{\"@keyframes spin{to{transform:rotate(360deg)}}\"}</style>\n    </div>\n  );\n}\n","frontend/src/lib/api.ts":"\"use client\";\n\n// src/lib/api.ts\nimport axios from \"axios\";\nimport { useAuthStore } from \"../store/auth.store\";\n\nexport const api = axios.create({\n  baseURL:         process.env.NEXT_PUBLIC_API_URL || \"http://localhost:5000/api\",\n  withCredentials: true,\n  headers:         { \"Content-Type\": \"application/json\" },\n  timeout:         30000,\n});\n\n// Public API - no auth, no redirects - for storefront use\nexport const publicApi = axios.create({\n  baseURL:  process.env.NEXT_PUBLIC_API_URL || \"http://localhost:5000/api\",\n  timeout:  30000,\n  headers:  { \"Content-Type\": \"application/json\" },\n});\n\napi.interceptors.request.use((config) => {\n  const token = useAuthStore.getState().accessToken;\n  if (token) config.headers.Authorization = `Bearer ${token}`;\n  \n  // CRITICAL: If sending FormData, delete the default Content-Type\n  // so the browser can set it correctly with the multipart boundary\n  if (config.data instanceof FormData) {\n    delete config.headers[\"Content-Type\"];\n    delete (config.headers as any)[\"content-type\"];\n  }\n  \n  return config;\n});\n\n// ── Refresh lock - prevents race condition ────────────────────\n// Only ONE refresh call happens at a time.\n// All other 401s queue up and wait for it.\nlet isRefreshing = false;\nlet refreshQueue: Array<(token: string) => void> = [];\n\nfunction processQueue(token: string) {\n  refreshQueue.forEach(resolve => resolve(token));\n  refreshQueue = [];\n}\n\n// ── Response interceptor ──────────────────────────────────────\napi.interceptors.response.use(\n  (res) => {\n    // Store refresh token when login succeeds\n    if ((res.config.url?.includes(\"/auth/login\") || res.config.url?.includes(\"/auth/register\")) && res.data?.data?.refreshToken) {\n      if (typeof window !== \"undefined\") {\n        localStorage.setItem(\"dropos-refresh-token\", res.data.data.refreshToken);\n      }\n      // Also set the access token immediately in store\n      if (res.data?.data?.accessToken) {\n        useAuthStore.getState().setAccessToken(res.data.data.accessToken);\n      }\n      // User is set by the mutation's onSuccess handler, not here\n    }\n    return res;\n  },\n  async (err) => {\n    const original = err.config;\n\n    if (err.response?.status !== 401 || original._retry) {\n      return Promise.reject(err);\n    }\n\n    // If already refreshing, queue this request\n    if (isRefreshing) {\n      return new Promise((resolve) => {\n        refreshQueue.push((newToken: string) => {\n          original.headers.Authorization = `Bearer ${newToken}`;\n          resolve(api(original));\n        });\n      });\n    }\n\n    // Mark as retrying so this exact request doesn't loop\n    original._retry = true;\n    isRefreshing = true;\n\n    try {\n      const storedRefreshToken = typeof window !== \"undefined\"\n        ? localStorage.getItem(\"dropos-refresh-token\")\n        : null;\n\n      const { data } = await axios.post(\n        `${process.env.NEXT_PUBLIC_API_URL || \"http://localhost:5000/api\"}/auth/refresh`,\n        { refreshToken: storedRefreshToken },\n        { withCredentials: true }\n      );\n\n      const newToken   = data.data?.accessToken;\n      const newRefresh = data.data?.refreshToken;\n\n      if (!newToken) throw new Error(\"No token in refresh response\");\n\n      // Save new tokens\n      useAuthStore.getState().setAccessToken(newToken);\n      if (newRefresh && typeof window !== \"undefined\") {\n        localStorage.setItem(\"dropos-refresh-token\", newRefresh);\n      }\n\n      // Update default header\n      api.defaults.headers.common[\"Authorization\"] = `Bearer ${newToken}`;\n\n      // Release all queued requests\n      processQueue(newToken);\n\n      // Retry original request\n      original.headers.Authorization = `Bearer ${newToken}`;\n      return api(original);\n\n    } catch (refreshError) {\n      // Refresh truly failed — clear stale token but don't spam redirects\n      refreshQueue = [];\n      isRefreshing = false;\n      if (typeof window !== \"undefined\") {\n        localStorage.removeItem(\"dropos-refresh-token\");\n        // Only redirect if we're actually inside the dashboard (not store or auth pages)\n        const path = window.location.pathname;\n        if (path.startsWith(\"/dashboard\") || path.startsWith(\"/admin\") || path.startsWith(\"/onboarding\")) {\n          useAuthStore.getState().logout();\n          window.location.href = \"/auth/login?expired=1\";\n        }\n      }\n      return Promise.reject(refreshError);\n    } finally {\n      isRefreshing = false;\n    }\n  }\n);\n\n// ── Namespaced API helpers ────────────────────────────────────\nexport const authAPI = {\n  login:           (d: any) => api.post(\"/auth/login\", d),\n  register:        (d: any) => api.post(\"/auth/register\", d),\n  logout:          ()       => api.post(\"/auth/logout\"),\n  getMe:           ()       => api.get(\"/auth/me\"),\n  updateProfile:   (d: any) => api.put(\"/auth/profile\", d),\n  forgotPassword:  (email: string) => api.post(\"/auth/forgot-password\", { email }),\n  resetPassword:   (token: string, password: string) => api.post(\"/auth/reset-password\", { token, password }),\n};\n\nexport const storeAPI = {\n  getAll:    ()           => api.get(\"/stores\"),\n  getOne:    (id: string) => api.get(`/stores/${id}`),\n  create:    (d: any)     => api.post(\"/stores\", d),\n  update:    (id: string, d: any) => api.patch(`/stores/${id}`, d),\n  delete:    (id: string) => api.delete(`/stores/${id}`),\n  getPublic: (slug: string) => publicApi.get(`/stores/public/${slug}`),\n};\n\nexport const productAPI = {\n  getAll:    (storeId: string, p?: any) => api.get(`/products/${storeId}`, { params: p }),\n  getOne:    (storeId: string, id: string) => api.get(`/products/${storeId}/${id}`),\n  create:    (storeId: string, d: any) => api.post(`/products/${storeId}`, d),\n  update:    (storeId: string, id: string, d: any) => api.put(`/products/${storeId}/${id}`, d),\n  delete:    (storeId: string, id: string) => api.delete(`/products/${storeId}/${id}`),\n  getPublicList: (storeId: string, p?: any) => publicApi.get(`/products/public/${storeId}`, { params: p }),\n  getPublicOne:  (storeId: string, id: string) => publicApi.get(`/products/public/${storeId}/${id}`),\n};\n\nexport const orderAPI = {\n  getAll:  (storeId: string, p?: any) => api.get(`/orders/${storeId}`, { params: p }),\n  getOne:  (storeId: string, id: string) => api.get(`/orders/${storeId}/${id}`),\n  create:  (storeId: string, d: any) => publicApi.post(`/orders/${storeId}`, d),\n  update:  (storeId: string, id: string, d: any) => api.patch(`/orders/${storeId}/${id}`, d),\n};\n\nexport const notificationAPI = {\n  getAll:   (p?: any) => api.get(\"/notifications\", { params: p }),\n  getCount: ()        => api.get(\"/notifications/count\"),\n  markRead: (id: string) => api.patch(`/notifications/${id}/read`),\n  markAllRead: ()     => api.patch(\"/notifications/read-all\"),\n};\n\nexport const uploadAPI = {\n  image: async (file: File, folder?: string): Promise<{ success: boolean; data: { url: string; publicId?: string } }> => {\n    const token = useAuthStore.getState().accessToken;\n    const BASE  = (process.env.NEXT_PUBLIC_API_URL || \"http://localhost:5000/api\").replace(/\\/api$/, \"\") + \"/api\";\n    const fd    = new FormData();\n    fd.append(\"image\", file);\n    if (folder) fd.append(\"folder\", folder);\n    const res = await fetch(`${BASE}/upload/image`, {\n      method:  \"POST\",\n      headers: token ? { Authorization: `Bearer ${token}` } : {},\n      body:    fd,\n    });\n    if (!res.ok) {\n      const err = await res.json().catch(() => ({ message: `Upload failed (${res.status})` }));\n      throw new Error(err.message || `Upload failed (${res.status})`);\n    }\n    const json = await res.json();\n    return json;\n  },\n  images: async (files: File[]): Promise<{ data: { data: { urls: string[] } } }> => {\n    const token = useAuthStore.getState().accessToken;\n    const BASE  = (process.env.NEXT_PUBLIC_API_URL || \"http://localhost:5000/api\").replace(/\\/api$/, \"\") + \"/api\";\n    const fd    = new FormData();\n    files.forEach(f => fd.append(\"images\", f));\n    const res = await fetch(`${BASE}/upload/images`, {\n      method:  \"POST\",\n      headers: token ? { Authorization: `Bearer ${token}` } : {},\n      body:    fd,\n    });\n    if (!res.ok) {\n      const err = await res.json().catch(() => ({ message: `Upload failed (${res.status})` }));\n      throw new Error(err.message || `Upload failed (${res.status})`);\n    }\n    return res.json();\n  },\n}\n\nexport const analyticsAPI = {\n  getSummary:  (storeId: string, period?: string) => api.get(`/analytics/${storeId}`, { params: { period } }),\n  getRevenue:  (storeId: string, period?: string) => api.get(`/analytics/${storeId}/revenue`, { params: { period } }),\n  getOrders:   (storeId: string, period?: string) => api.get(`/analytics/${storeId}/orders`, { params: { period } }),\n  getProducts: (storeId: string) => api.get(`/analytics/${storeId}/products`),\n  getCustomers:(storeId: string) => api.get(`/analytics/${storeId}/customers`),\n};\n\nexport const adminAPI = {\n  getStats:           ()                    => api.get(\"/admin/stats\"),\n  get:                (url: string, cfg?: any) => api.get(url, cfg),\n  post:               (url: string, data?: any) => api.post(url, data),\n  patch:              (url: string, data?: any) => api.patch(url, data),\n  put:                (url: string, data?: any) => api.put(url, data),\n  delete:             (url: string)            => api.delete(url),\n  getDashboard:       ()                    => api.get(\"/admin/stats\"),\n  getRevenue:         ()                    => api.get(\"/admin/revenue\"),\n  getUsers:           (p?: any)             => api.get(\"/admin/users\", { params: p }),\n  getUser:            (id: string)          => api.get(`/admin/users/${id}`),\n  banUser:            (id: string)          => api.patch(`/admin/users/${id}/ban`),\n  unbanUser:          (id: string)          => api.patch(`/admin/users/${id}/unban`),\n  deleteUser:         (id: string)          => api.delete(`/admin/users/${id}`),\n  updateSubscription: (id: string, d: any)  => api.patch(`/admin/users/${id}/subscription`, d),\n  getAnalytics:       (p?: any)             => api.get(\"/admin/analytics\", { params: p }),\n  getPayments:        (p?: any)             => api.get(\"/admin/payments\",  { params: p }),\n  getTickets:         (p?: any)             => api.get(\"/admin/support\",   { params: p }),\n  updateTicket:       (id: string, d: any)  => api.patch(`/admin/support/${id}`, d),\n  getErrorLogs:       (p?: any)             => api.get(\"/admin/error-logs\",{ params: p }),\n  resolveError:       (id: string)          => api.patch(`/admin/error-logs/${id}/resolve`),\n  getAuditLogs:       (p?: any)             => api.get(\"/admin/audit-logs\",{ params: p }),\n  getSettings:        ()                    => api.get(\"/admin/settings\"),\n  updateSettings:     (d: any)              => api.patch(\"/admin/settings\", d),\n  getWaitlist:        (p?: any)             => api.get(\"/admin/waitlist\",  { params: p }),\n}","frontend/src/app/dashboard/page.tsx":"\"use client\";\nimport { useState, useEffect } from \"react\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { motion } from \"framer-motion\";\nimport Link from \"next/link\";\n// currency formatting handled inline\nimport {\n  TrendingUp, ShoppingCart, Users, Package, Zap,\n  ChevronRight, Store, Flame, Activity, ArrowUpRight,\n  AlertCircle, Clock, CheckCircle2, RefreshCw\n} from \"lucide-react\";\nimport { useTheme } from \"../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../store/auth.store\";\nimport { api } from \"../../lib/api\";\nimport { OpportunityFeed } from \"../../components/kai/OpportunityFeed\";\nimport { OnboardingTips } from \"../../components/dashboard/OnboardingTips\";\n\nconst V = { v500: \"#6B35E8\", v400: \"#8B5CF6\", v300: \"#A78BFA\", cyan: \"#06B6D4\", green: \"#10B981\", amber: \"#F59E0B\", red: \"#EF4444\" };\n\nconst fmt = (n: number) => new Intl.NumberFormat(\"en-NG\", { style:\"currency\", currency:\"NGN\", maximumFractionDigits:0 }).format(n||0);\n\nfunction StatCard({ label, value, delta, color, icon: Icon, delay = 0 }: any) {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = { card: isDark ? \"#181230\" : \"#fff\", border: isDark ? \"rgba(255,255,255,0.06)\" : \"rgba(15,5,32,0.07)\", text: isDark ? \"#fff\" : \"#0D0918\", muted: isDark ? \"rgba(255,255,255,0.38)\" : \"rgba(13,9,24,0.45)\" };\n  return (\n    <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay }}\n      style={{ padding: 18, borderRadius: 16, background: t.card, border: `1px solid ${t.border}` }}>\n      <div style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\", marginBottom: 12 }}>\n        <div style={{ width: 36, height: 36, borderRadius: 10, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", background: `${color}18` }}>\n          <Icon size={16} color={color} />\n        </div>\n        {delta !== undefined && (\n          <span style={{ fontSize: 11, fontWeight: 700, color: delta >= 0 ? V.green : V.red, background: delta >= 0 ? \"rgba(16,185,129,0.1)\" : \"rgba(239,68,68,0.1)\", padding: \"3px 8px\", borderRadius: 99 }}>\n            {delta >= 0 ? \"+\" : \"\"}{delta}%\n          </span>\n        )}\n      </div>\n      <p style={{ fontSize: 22, fontWeight: 900, color: t.text, letterSpacing: \"-0.04em\", lineHeight: 1 }}>{value}</p>\n      <p style={{ fontSize: 12, color: t.muted, marginTop: 4 }}>{label}</p>\n    </motion.div>\n  );\n}\n\nfunction OrderRow({ order, t }: any) {\n  const statusColors: Record<string, string> = {\n    PENDING: V.amber, COMPLETED: V.green, SHIPPED: V.cyan,\n    DELIVERED: V.v400, CANCELLED: V.red, PROCESSING: V.cyan,\n  };\n  const color = statusColors[order.status] || V.amber;\n  return (\n    <div style={{ display: \"flex\", alignItems: \"center\", gap: 12, padding: \"10px 0\", borderBottom: `1px solid ${t.border}` }}>\n      <div style={{ width: 32, height: 32, borderRadius: 8, background: `${color}15`, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", flexShrink: 0 }}>\n        <ShoppingCart size={13} color={color} />\n      </div>\n      <div style={{ flex: 1, minWidth: 0 }}>\n        <p style={{ fontSize: 13, fontWeight: 600, color: t.text, whiteSpace: \"nowrap\", overflow: \"hidden\", textOverflow: \"ellipsis\" }}>\n          {order.customerName || \"Customer\"}\n        </p>\n        <p style={{ fontSize: 11, color: t.muted, marginTop: 1 }}>#{order.orderNumber || order.id?.slice(-6)}</p>\n      </div>\n      <div style={{ textAlign: \"right\", flexShrink: 0 }}>\n        <p style={{ fontSize: 13, fontWeight: 700, color: t.text }}>{fmt(order.total)}</p>\n        <span style={{ fontSize: 10, fontWeight: 700, color, background: `${color}15`, padding: \"2px 6px\", borderRadius: 99 }}>\n          {order.status}\n        </span>\n      </div>\n    </div>\n  );\n}\n\nexport default function DashboardPage() {\n  const { theme } = useTheme();\n  const { user } = useAuthStore();\n  const isDark = theme === \"dark\";\n  const [greeting, setGreeting] = useState(\"morning\");\n  const storeCurrency = (user?.stores?.[0] as any)?.currency || \"NGN\";\n  const fmtCurrency = (n: number) => {\n    const symbol = storeCurrency === \"NGN\" ? \"₦\" : storeCurrency === \"GBP\" ? \"£\" : storeCurrency === \"USD\" ? \"$\" : \"₦\";\n    return `${symbol}${(n || 0).toLocaleString(\"en-NG\", { maximumFractionDigits: 0 })}`;\n  };\n  const firstName = user?.name?.split(\" \")[0] || user?.email?.split(\"@\")[0] || \"there\";\n  const storeId = user?.stores?.[0]?.id;\n  const storeSlug = user?.stores?.[0]?.slug;\n\n  useEffect(() => {\n    const h = new Date().getHours();\n    setGreeting(h < 12 ? \"morning\" : h < 17 ? \"afternoon\" : \"evening\");\n  }, []);\n\n  const t = {\n    card:   isDark ? \"#181230\" : \"#fff\",\n    border: isDark ? \"rgba(255,255,255,0.06)\" : \"rgba(15,5,32,0.07)\",\n    text:   isDark ? \"#fff\"    : \"#0D0918\",\n    muted:  isDark ? \"rgba(255,255,255,0.38)\" : \"rgba(13,9,24,0.45)\",\n    faint:  isDark ? \"rgba(255,255,255,0.03)\" : \"rgba(15,5,32,0.02)\",\n  };\n\n  const { data: analytics } = useQuery({\n    queryKey: [\"dashboard-analytics\", storeId],\n    queryFn:  () => api.get(`/analytics/${storeId}?period=7`).then(r => r.data.data),\n    enabled:  !!storeId,\n    staleTime: 60000,\n  });\n\n  const { data: recentOrders } = useQuery({\n    queryKey: [\"dashboard-orders\", storeId],\n    queryFn:  () => api.get(`/orders/${storeId}?limit=5`).then(r => r.data.data?.orders || r.data.data || []),\n    enabled:  !!storeId,\n    staleTime: 30000,\n  });\n\n  // Direct product count — more reliable than analytics which may be cached\n  const { data: productCount } = useQuery({\n    queryKey: [\"dashboard-product-count\", storeId],\n    queryFn:  () => api.get(`/products/${storeId}?limit=1`).then(r => {\n      const d = r.data;\n      return d.data?.pagination?.total || d.pagination?.total || d.data?.total || d.total ||\n             (Array.isArray(d.data?.products) ? d.data.products.length : 0) ||\n             (Array.isArray(d.data) ? d.data.length : 0) || 0;\n    }),\n    enabled:  !!storeId,\n    staleTime: 60000,\n  });\n\n  const { data: pulse } = useQuery({\n    queryKey: [\"kiro-pulse\", storeId],\n    queryFn:  () => api.get(`/kai/pulse?storeId=${storeId}&limit=3`).then(r => r.data.data || []),\n    enabled:  !!storeId,\n    staleTime: 120000,\n  });\n\n  const stats = analytics?.summary || analytics?.stats || {};\n  const orders = Array.isArray(recentOrders) ? recentOrders : [];\n  // Deduplicate by type — keep most recent of each type, max 4\n  const seen = new Set<string>();\n  const alerts = (Array.isArray(pulse) ? pulse : [])\n    .filter((a: any) => { if (seen.has(a.type)) return false; seen.add(a.type); return true; })\n    .slice(0, 4);\n\n  const statCards = [\n    { label: \"Revenue (7d)\",  value: fmtCurrency(stats.revenue || 0),        delta: stats.revenueDelta,  color: V.v400,  icon: TrendingUp  },\n    { label: \"Orders (7d)\",   value: (stats.orders    || 0).toLocaleString(), delta: stats.ordersDelta,   color: V.cyan,  icon: ShoppingCart },\n    { label: \"Customers\",     value: (stats.customers || 0).toLocaleString(), delta: undefined,            color: V.green, icon: Users        },\n    { label: \"Products\",      value: (productCount || stats.products || analytics?.totalProducts || 0).toLocaleString(), delta: undefined, color: V.amber, icon: Package },\n  ];\n\n  const quickActions = [\n    { label: \"Add Product\",  href: \"/dashboard/products\",   icon: Package,   color: V.v400  },\n    { label: \"View Store\",   href: storeSlug ? `/store/${storeSlug}` : \"/dashboard/stores\", icon: Store, color: V.cyan, target: \"_blank\" },\n    { label: \"Flash Sale\",   href: \"/dashboard/flash-sales\",icon: Flame,     color: V.amber },\n    { label: \"Analytics\",    href: \"/dashboard/analytics\",  icon: Activity,  color: V.green },\n  ];\n\n  return (\n    <div style={{ maxWidth: 1200, margin: \"0 auto\" }}>\n      {/* Header */}\n      <motion.div initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }} style={{ marginBottom: 24 }}>\n        <h1 style={{ fontSize: 22, fontWeight: 900, letterSpacing: \"-0.04em\", color: t.text, marginBottom: 4 }}>\n          Good {greeting}, {firstName} 👋\n        </h1>\n        <p style={{ fontSize: 13, color: t.muted }}>\n          {user?.stores?.[0]?.name || \"Your store\"} · {new Date().toLocaleDateString(\"en-NG\", { weekday: \"long\", day: \"numeric\", month: \"long\" })}\n        </p>\n      </motion.div>\n\n      {/* Stats */}\n      <div style={{ display: \"grid\", gridTemplateColumns: \"repeat(4,1fr)\", gap: 12, marginBottom: 20 }} className=\"grid-cols-2 sm:grid-cols-4\">\n        {statCards.map((s, i) => <StatCard key={s.label} {...s} delay={i * 0.07} />)}\n      </div>\n\n      <div style={{ display: \"grid\", gridTemplateColumns: \"1fr 340px\", gap: 16 }} className=\"grid-1col lg:grid-2col\">\n        {/* Left: Recent Orders */}\n        <div>\n          <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }}\n            style={{ padding: 18, borderRadius: 16, background: t.card, border: `1px solid ${t.border}`, marginBottom: 16 }}>\n            <div style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\", marginBottom: 14 }}>\n              <span style={{ fontSize: 13, fontWeight: 700, color: t.text }}>Recent Orders</span>\n              <Link href=\"/dashboard/orders\" style={{ display: \"flex\", alignItems: \"center\", gap: 4, fontSize: 12, color: V.v400, textDecoration: \"none\", fontWeight: 600 }}>\n                View all <ChevronRight size={13} />\n              </Link>\n            </div>\n            {orders.length === 0 ? (\n              <div style={{ textAlign: \"center\", padding: \"28px 0\" }}>\n                <ShoppingCart size={28} style={{ color: t.muted, margin: \"0 auto 8px\" }} />\n                <p style={{ fontSize: 12, color: t.muted }}>No orders yet. Share your store link to get your first sale.</p>\n                {storeSlug && (\n                  <a href={`/store/${storeSlug}`} target=\"_blank\" rel=\"noreferrer\"\n                    style={{ display: \"inline-flex\", alignItems: \"center\", gap: 6, marginTop: 12, fontSize: 12, fontWeight: 700, color: V.v400, textDecoration: \"none\", background: \"rgba(107,53,232,0.08)\", padding: \"6px 14px\", borderRadius: 99, border: \"1px solid rgba(107,53,232,0.2)\" }}>\n                    <Store size={11} /> View your store <ArrowUpRight size={11} />\n                  </a>\n                )}\n              </div>\n            ) : (\n              <div>\n                {orders.slice(0, 5).map((o: any) => <OrderRow key={o.id} order={o} t={t} />)}\n              </div>\n            )}\n          </motion.div>\n\n          {/* Onboarding tips for new users */}\n          {storeId && (\n            <OnboardingTips\n              isDark={isDark}\n              storeSlug={storeSlug || \"\"}\n              completedSteps={[\n                ...(user?.stores?.[0]?.id ? [\"store\"] : []),\n                ...((productCount || 0) > 0 ? [\"product\"] : []),\n                ...(orders.length > 0 ? [\"kiro\"] : []),\n                ...(!!(user?.stores?.[0] as any)?.paystackPublicKey || !!(user?.stores?.[0] as any)?.stripeAccountId ? [\"payment\"] : []),\n              ]}\n            />\n          )}\n\n          {/* KIRO Opportunity Feed - proactive intelligence */}\n          {storeId && <OpportunityFeed storeId={storeId} isDark={isDark} onAction={(action) => {\n            // Trigger KIRO chat with the action\n            if (typeof window !== \"undefined\") {\n              window.dispatchEvent(new CustomEvent(\"kiro:execute\", { detail: { prompt: action } }));\n            }\n          }}/>}\n\n          {/* KIRO Pulse Alerts */}\n          {alerts.length > 0 && (\n            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.4 }}\n              style={{ padding: 18, borderRadius: 16, background: t.card, border: `1px solid ${t.border}` }}>\n              <div style={{ display: \"flex\", alignItems: \"center\", gap: 8, marginBottom: 14 }}>\n                <Zap size={14} color={V.v400} />\n                <span style={{ fontSize: 13, fontWeight: 700, color: t.text }}>KIRO Alerts</span>\n              </div>\n              <div style={{ display: \"flex\", flexDirection: \"column\", gap: 8 }}>\n                {alerts.map((a: any) => (\n                  <div key={a.id} style={{ display: \"flex\", gap: 10, padding: 10, borderRadius: 10, background: t.faint, border: `1px solid ${t.border}` }}>\n                    <AlertCircle size={13} color={a.severity === \"high\" ? V.red : V.amber} style={{ flexShrink: 0, marginTop: 1 }} />\n                    <div>\n                      <p style={{ fontSize: 12, fontWeight: 600, color: t.text }}>{a.title}</p>\n                      <p style={{ fontSize: 11, color: t.muted, marginTop: 2 }}>{a.message}</p>\n                    </div>\n                  </div>\n                ))}\n              </div>\n            </motion.div>\n          )}\n        </div>\n\n        {/* Right column */}\n        <div style={{ display: \"flex\", flexDirection: \"column\", gap: 14 }}>\n          {/* KIRO CTA */}\n          <motion.div initial={{ opacity: 0, x: 16 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.25 }}\n            style={{ padding: 18, borderRadius: 16, background: \"linear-gradient(135deg,#2D1B69,#1a0f3c)\", border: \"1px solid rgba(107,53,232,0.3)\", position: \"relative\", overflow: \"hidden\" }}>\n            <div style={{ position: \"absolute\", top: -20, right: -20, width: 80, height: 80, borderRadius: \"50%\", background: \"rgba(107,53,232,0.15)\" }} />\n            <div style={{ display: \"flex\", alignItems: \"center\", gap: 8, marginBottom: 8 }}>\n              <div style={{ width: 28, height: 28, borderRadius: 8, background: \"rgba(107,53,232,0.3)\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\" }}>\n                <Zap size={13} color={V.v300} />\n              </div>\n              <span style={{ fontSize: 12, fontWeight: 700, color: V.v300 }}>KIRO</span>\n            </div>\n            <p style={{ fontSize: 13, fontWeight: 700, color: \"#fff\", marginBottom: 6 }}>What do you want to build today?</p>\n            <p style={{ fontSize: 11, color: \"rgba(255,255,255,0.5)\", marginBottom: 14, lineHeight: 1.5 }}>\n              Import products, write copy, run a sale, or just ask anything about your store.\n            </p>\n            <Link href=\"/kiro\">\n              <button style={{ width: \"100%\", padding: \"9px 0\", borderRadius: 10, border: \"none\", cursor: \"pointer\", background: \"rgba(107,53,232,0.4)\", color: \"#fff\", fontSize: 12, fontWeight: 700, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", gap: 6 }}>\n                <Zap size={12} /> Chat with KIRO\n              </button>\n            </Link>\n          </motion.div>\n\n          {/* Quick Actions */}\n          <motion.div initial={{ opacity: 0, x: 16 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.32 }}\n            style={{ padding: 18, borderRadius: 16, background: t.card, border: `1px solid ${t.border}` }}>\n            <span style={{ fontSize: 13, fontWeight: 700, color: t.text, display: \"block\", marginBottom: 12 }}>Quick Actions</span>\n            <div style={{ display: \"grid\", gridTemplateColumns: \"1fr 1fr\", gap: 8 }}>\n              {quickActions.map(a => {\n                const Icon = a.icon;\n                return (\n                  <Link key={a.label} href={a.href} target={(a as any).target} style={{ textDecoration: \"none\" }}>\n                    <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.97 }}\n                      style={{ display: \"flex\", flexDirection: \"column\", alignItems: \"center\", gap: 7, padding: 12, borderRadius: 12, cursor: \"pointer\", background: t.faint, border: `1px solid ${t.border}` }}>\n                      <div style={{ width: 30, height: 30, borderRadius: 9, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", background: `${a.color}15` }}>\n                        <Icon size={14} color={a.color} />\n                      </div>\n                      <span style={{ fontSize: 11, fontWeight: 600, color: t.muted, textAlign: \"center\" }}>{a.label}</span>\n                    </motion.div>\n                  </Link>\n                );\n              })}\n            </div>\n          </motion.div>\n\n          {/* Store status */}\n          <motion.div initial={{ opacity: 0, x: 16 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.38 }}\n            style={{ padding: 18, borderRadius: 16, background: t.card, border: `1px solid ${t.border}` }}>\n            <span style={{ fontSize: 13, fontWeight: 700, color: t.text, display: \"block\", marginBottom: 12 }}>Store Status</span>\n            <div style={{ display: \"flex\", flexDirection: \"column\", gap: 8 }}>\n              {[\n                { label: \"Store live\",     done: !!user?.stores?.[0]?.id,                                                                               icon: Store        },\n                { label: \"Products added\", done: (productCount || stats?.products || analytics?.totalProducts || 0) > 0,              icon: Package      },\n                { label: \"First order\",    done: orders.length > 0 || (stats?.orders || analytics?.totalOrders || 0) > 0,                             icon: ShoppingCart },\n                { label: \"Payment setup\",  done: !!(user?.stores?.[0] as any)?.paystackPublicKey || !!(user?.stores?.[0] as any)?.stripeAccountId || !!(user?.stores?.[0] as any)?.currency, icon: CheckCircle2 },\n              ].map(item => {\n                const Icon = item.icon;\n                return (\n                  <div key={item.label} style={{ display: \"flex\", alignItems: \"center\", gap: 8 }}>\n                    <div style={{ width: 22, height: 22, borderRadius: 6, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", background: item.done ? \"rgba(16,185,129,0.1)\" : t.faint, flexShrink: 0 }}>\n                      <Icon size={11} color={item.done ? V.green : t.muted} />\n                    </div>\n                    <span style={{ fontSize: 12, color: item.done ? t.text : t.muted, flex: 1 }}>{item.label}</span>\n                    {item.done\n                      ? <CheckCircle2 size={13} color={V.green} />\n                      : <Clock size={13} style={{ color: t.muted }} />}\n                  </div>\n                );\n              })}\n            </div>\n          </motion.div>\n        </div>\n      </div>\n\n      <style>{`\n        @media(max-width:900px){\n          .grid-cols-2{grid-template-columns:1fr 1fr!important}\n          .grid-1col.lg\\\\:grid-2col{grid-template-columns:1fr!important}\n        }\n        @media(max-width:480px){\n          .grid-cols-2{grid-template-columns:1fr 1fr!important}\n        }\n      `}</style>\n    </div>\n  );\n}\n","frontend/public/favicon.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 32 32\">\n  <defs>\n    <linearGradient id=\"bg\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#6B35E8\"/>\n      <stop offset=\"100%\" stop-color=\"#2A0D7A\"/>\n    </linearGradient>\n  </defs>\n  <rect width=\"32\" height=\"32\" rx=\"7\" fill=\"url(#bg)\"/>\n  <path d=\"M18.5 4.5 L11 17 H15.5 L13.5 27.5 L22 15 H17 L19.5 4.5 Z\" fill=\"white\"/>\n</svg>\n"};
